package io.theficos.comanda.data.local

import androidx.room.*
import kotlinx.serialization.Serializable

// Defaults for unbound in-memory fixtures. Production scopes are generated by initializeLocalList.
const val LOCAL_LIST_ID = "00000000-0000-4000-8000-000000000001"
const val LOCAL_HOUSEHOLD_ID = "00000000-0000-4000-8000-000000000002"

@Entity(tableName = "household")
data class HouseholdEntity(@PrimaryKey val id: String, val shared: Boolean = false, val routing: String? = null)
@Serializable
@Entity(tableName = "list_scope", indices = [Index("householdId")])
data class ListEntity(@PrimaryKey val id: String, val householdId: String, val name: String, val shared: Boolean = false, val archived: Boolean = false, val archiveSource: String? = null)
@Entity(tableName = "list_selection")
data class ListSelectionEntity(@PrimaryKey val singleton: Int = 1, val listId: String)
@Entity(tableName = "item_pref", primaryKeys = ["listId", "key"])
data class SharedPreferenceEntity(val listId: String, val key: String, val category: String?, val repeatEveryDays: Int?)
@Entity(tableName = "local_item_pref", primaryKeys = ["listId", "key"])
data class LocalPreferenceEntity(val listId: String, val key: String, val muted: Boolean, val snoozedUntil: Long?)
@Entity(tableName = "sync_projection")
data class ProjectionEntity(@PrimaryKey val listId: String, val confirmed: String, val optimistic: String)
@Entity(tableName = "sync_outbox", primaryKeys = ["listId", "intentId"], indices = [Index("listId", "ordinal", unique = true)])
data class OutboxEntity(val listId: String, val intentId: String, val ordinal: Long, val command: String, val envelope: ByteArray? = null, val acknowledged: Boolean = false)
@Entity(tableName = "sync_received", primaryKeys = ["listId", "seq"], indices = [Index("listId", "intentId", unique = true), Index("listId", "envelopeId", unique = true)])
data class ReceivedEntity(val listId: String, val seq: Long, val intentId: String, val envelopeId: String, val digest: String, val head: String)
@Entity(tableName = "sync_cursor")
data class CursorEntity(@PrimaryKey val listId: String, val seq: Long, val head: String, val epoch: Long, val manifestHash: String)
@Entity(tableName = "member_ref", primaryKeys = ["householdId", "id"])
data class MemberEntity(val householdId: String, val id: String, val proof: String)
@Entity(tableName = "device_ref", primaryKeys = ["householdId", "id"])
data class DeviceEntity(val householdId: String, val id: String, val memberId: String, val proof: String)

/** Local review choices never enter an encrypted snapshot or a shopping archive. */
@Entity(tableName = "conflict_dismissal", primaryKeys = ["listId", "intentId"])
data class ConflictDismissalEntity(val listId: String, val intentId: String)
